<?php
require __DIR__ . '/auth.php'; migrate_legacy_data(); require_login(); $created = [];
if ($_SERVER['REQUEST_METHOD'] === 'POST') { require_csrf(); $screen = (string) ($_POST['screen'] ?? ''); if (!valid_screen($screen)) { http_response_code(400); exit('Unbekanntes Display.'); }
    with_data_lock(function () use ($screen, &$created): void { $data = auth_data(); $token = new_device_token(); $data['screens'][$screen] = ['token_hash' => token_hash($token), 'updated_at' => gmdate('c')]; save_auth_data($data); $created[$screen] = $token; });
}
?><!doctype html><html lang="de"><meta charset="utf-8"><title>Displays</title><body><h1>Displays</h1><p>Beim Erzeugen eines neuen Tokens wird das bisherige sofort ungültig. Hinterlegen Sie die angezeigte URL ausschließlich auf dem zugehörigen Display.</p>
<?php foreach (SCREEN_IDS as $screen): ?><section><h2><?= h(ucfirst($screen)) ?></h2><?php if (isset($created[$screen])): $url = 'display.php?screen=' . rawurlencode($screen) . '&token=' . rawurlencode($created[$screen]); ?><p><strong>Neue Display-URL (nur einmal anzeigen):</strong><br><code><?= h($url) ?></code></p><?php elseif (isset(auth_data()['screens'][$screen])): ?><p>Token eingerichtet.</p><?php else: ?><p>Noch kein Token eingerichtet.</p><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="screen" value="<?= h($screen) ?>"><button>Token <?= isset(auth_data()['screens'][$screen]) ? 'erneuern' : 'erzeugen' ?></button></form></section><?php endforeach; ?><p><a href="formular.php">Zur Verwaltung</a></p></body></html>
